/**
 * PM2 Ecosystem Configuration for Agent ${AGENT_ID}
 *
 * Auto-generated by launch.sh — do not edit manually.
 * Customize ecosystem.agent.template.cjs in .har/ to change processes.
 */

// launch.sh writes this file (and .env.agent.N) to the work dir root,
// so __dirname IS the work dir — repo root or the agent's git worktree.
const fs = require('fs');
const path = require('path');

// Tiny inline .env parser — avoids depending on the `dotenv` package, which
// this project does not otherwise need.
function parseEnvFile(filePath) {
  const env = {};
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch {
    return env;
  }
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    let value = trimmed.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    env[key] = value;
  }
  return env;
}

const agentEnvPath = path.resolve(__dirname, '.env.agent.${AGENT_ID}');
const env = parseEnvFile(agentEnvPath);

// This repo is a single Next.js app — one process serves the frontend, API
// routes, and server actions together. There is no separate backend to run.
const port = env.FE_PORT || env.PORT || 3000;

module.exports = {
  apps: [
    {
      name: 'har-${HARNESS_PROJECT_NAME}-agent-${AGENT_ID}-web',
      script: 'npm',
      args: `run dev -- -p ${port}`,
      interpreter: 'none',
      cwd: __dirname,
      env: {
        ...env,
        NODE_ENV: 'development',
        PORT: port,
      },
      watch: false,
      autorestart: true,
      kill_timeout: 5000,
      merge_logs: true,
      time: true,
    },
  ],
};
